create table if not exists public.fcq_enrollments(id uuid primary key default gen_random_uuid(),school text not null default 'primary4',year text not null default '2026-27',class_name text not null check(class_name in ('4A','4B','4C')),student_no integer not null check(student_no between 1 and 25),unique(school,year,class_name,student_no));
insert into public.fcq_enrollments(class_name,student_no) select c,n from unnest(array['4A','4B','4C']) c cross join generate_series(1,25) n on conflict do nothing;
create table if not exists public.fcq_settings(key text primary key,value jsonb not null);
create table if not exists public.fcq_sessions(token_hash text primary key,enrollment_id uuid references public.fcq_enrollments(id),teacher boolean not null default false,expires_at timestamptz not null,created_at timestamptz not null default now());
create index if not exists fcq_sessions_expiry on public.fcq_sessions(expires_at);
create table if not exists public.fcq_discoveries(enrollment_id uuid references public.fcq_enrollments(id) not null,biome text not null,species_id text not null,first_at timestamptz not null default now(),primary key(enrollment_id,biome,species_id));
create table if not exists public.fcq_chains(enrollment_id uuid references public.fcq_enrollments(id) not null,biome text not null,version text not null,signature text not null,nodes jsonb not null,first_at timestamptz not null default now(),primary key(enrollment_id,biome,version,signature));
create table if not exists public.fcq_events(enrollment_id uuid references public.fcq_enrollments(id) not null,event_id uuid not null,biome text not null,type text not null,result jsonb not null,received_at timestamptz not null default now(),primary key(enrollment_id,event_id));
create table if not exists public.fcq_activity(enrollment_id uuid references public.fcq_enrollments(id) not null,biome text not null,arrow boolean not null default false,primary key(enrollment_id,biome));
create table if not exists public.fcq_limits(bucket text primary key,attempts integer not null default 0,reset_at timestamptz not null);
alter table public.fcq_enrollments enable row level security;
alter table public.fcq_settings enable row level security;
alter table public.fcq_sessions enable row level security;
alter table public.fcq_discoveries enable row level security;
alter table public.fcq_chains enable row level security;
alter table public.fcq_events enable row level security;
alter table public.fcq_activity enable row level security;
alter table public.fcq_limits enable row level security;
revoke all on public.fcq_enrollments,public.fcq_settings,public.fcq_sessions,public.fcq_discoveries,public.fcq_chains,public.fcq_events,public.fcq_activity,public.fcq_limits from anon,authenticated;
grant all on public.fcq_enrollments,public.fcq_settings,public.fcq_sessions,public.fcq_discoveries,public.fcq_chains,public.fcq_events,public.fcq_activity,public.fcq_limits to service_role;
create or replace function public.fcq_rate(bucket_key text) returns integer language sql security invoker set search_path='' as $$ insert into public.fcq_limits(bucket,attempts,reset_at) values(bucket_key,1,now()+interval '10 minutes') on conflict(bucket) do update set attempts=case when fcq_limits.reset_at<now() then 1 else fcq_limits.attempts+1 end,reset_at=case when fcq_limits.reset_at<now() then now()+interval '10 minutes' else fcq_limits.reset_at end returning attempts $$;
revoke all on function public.fcq_rate(text) from public,anon,authenticated;
grant execute on function public.fcq_rate(text) to service_role;
